import json,numpy as np
from itertools import product
rows=[]
for f in ['batch1.out','batch2.out']:
    for r in json.load(open(f))['results']:
        if r['svc']=='train' and r['status']=='ok':
            c=r['config']; rows.append((c['method'],c['n'],c['steps'],c['len_pen'],r['kl'],r['proxy_reward'],r['mean_len']))
rows.append(('ppo',1,945,0.0,4.602123,1.86817,620.498))
len0=215.345
groups={}
for m,n,s,lp,kl,pr,ln in rows:
    key=(m,n,s) if (m=='bon' and n in (4,32)) or (m=='ppo' and s==945) else None
    if key: groups.setdefault(key,[]).append((ln,pr))
keys=list(groups)
def fit(form):
    X=[];Y=[]
    for i,k in enumerate(keys):
        for ln,pr in groups[k]:
            row=[0]*len(keys); row[i]=1; row.append(form(ln)); X.append(row); Y.append(pr)
    X=np.array(X);Y=np.array(Y)
    coef,rss,_,_=np.linalg.lstsq(X,Y,rcond=None)
    return coef,rss[0]
best=[]
for lam in np.linspace(40,600,113):
    coef,rss=fit(lambda x:1-np.exp(-(x-len0)/lam)); best.append((rss,'exp',lam,coef))
for k in np.linspace(0.2,4,39):
    coef,rss=fit(lambda x:1-(len0/x)**k); best.append((rss,'pow',k,coef))
for lam in np.linspace(40,600,57):
    coef,rss=fit(lambda x:np.tanh((x-len0)/lam)); best.append((rss,'tanh',lam,coef))
for lam in np.linspace(20,600,59):
    coef,rss=fit(lambda x:(x-len0)/(x-len0+lam)); best.append((rss,'hill',lam,coef))
coef,rss=fit(lambda x:np.log(x/len0)); best.append((rss,'log',0,coef))
coef,rss=fit(lambda x:x-len0); best.append((rss,'lin',0,coef))
best.sort(key=lambda t:t[0])
for rss,name,p,coef in best[:12]:
    A=coef[-1]
    if name=='exp': L=A*(1-np.exp(-(620.498-len0)/p))
    elif name=='pow': L=A*(1-(len0/620.498)**p)
    elif name=='tanh': L=A*np.tanh((620.498-len0)/p)
    elif name=='hill': L=A*(620.498-len0)/(620.498-len0+p)
    elif name=='log': L=A*np.log(620.498/len0)
    else: L=A*(620.498-len0)
    print(f"{name:5} p={p:7.2f} rss={rss:.5f} A={A:.4f} Q={coef[:-1].round(4)} L(620.5)={L:.4f} frac={L/1.868:.4f}")
print("---- per-family best")
for fam in ['exp','pow','tanh','hill','log','lin']:
    b=[t for t in best if t[1]==fam][0]; print(fam,b[0],b[2])
